package wgmodern;
import java.util.*;import java.util.concurrent.CompletableFuture;import net.minecraft.data.CachedOutput;import static wgmodern.WGData.map;
public class CreativeDeviceData {
 static Object box(double x,double y,double z,double X,double Y,double Z){var faces=map();for(var f:List.of("north","south","east","west","up","down"))faces.put(f,map("texture",f.equals("up")||f.equals("down")?"#top":"#side"));return map("from",List.of(x,y,z),"to",List.of(X,Y,Z),"faces",faces);}
 public static void add(WGData d,CachedOutput c,List<CompletableFuture<?>> jobs){
  for(String id:List.of("magic_tile_lock","obsidian_plate","obsidian_decoration")){String texture=id.equals("magic_tile_lock")?"magictilelock":id.equals("obsidian_plate")?"obsidianplate":"obsidiandecoration0";jobs.add(d.save(c,"assets/witchinggadgets/models/item/"+id+".json",map("parent","minecraft:block/cube_all","textures",map("all","witchinggadgets:blocks/"+texture))));jobs.add(d.save(c,"data/witchinggadgets/loot_tables/blocks/"+id+".json",map("type","minecraft:block","pools",List.of(map("rolls",1,"entries",List.of(map("type","minecraft:item","name","witchinggadgets:"+id)))))));}
  jobs.add(d.save(c,"assets/witchinggadgets/models/block/obsidian_plate.json",map("parent","minecraft:block/cube_all","textures",map("all","witchinggadgets:blocks/obsidianplate"))));jobs.add(d.save(c,"assets/witchinggadgets/blockstates/obsidian_plate.json",map("variants",map("",map("model","witchinggadgets:block/obsidian_plate")))));
  var variants=map();for(int n=0;n<3;n++){jobs.add(d.save(c,"assets/witchinggadgets/models/block/obsidian_decoration_"+n+".json",map("parent","minecraft:block/cube_all","textures",map("all","witchinggadgets:blocks/obsidiandecoration"+n))));variants.put("variant="+n,map("model","witchinggadgets:block/obsidian_decoration_"+n));}jobs.add(d.save(c,"assets/witchinggadgets/blockstates/obsidian_decoration.json",map("variants",variants)));
  var elements=new ArrayList<>();for(int x:List.of(0,12))for(int z:List.of(0,12))elements.add(box(x,0,z,x+4,16,z+4));for(int y:List.of(0,12)){elements.add(box(4,y,0,12,y+4,4));elements.add(box(0,y,4,4,y+4,12));elements.add(box(4,y,12,12,y+4,16));elements.add(box(12,y,4,16,y+4,12));}elements.add(box(1,1,1,15,15,15));jobs.add(d.save(c,"assets/witchinggadgets/models/block/magic_tile_lock.json",map("parent","minecraft:block/block","textures",map("side","witchinggadgets:blocks/magictilelock","top","witchinggadgets:blocks/magictilelock","particle","witchinggadgets:blocks/magictilelock"),"elements",elements)));jobs.add(d.save(c,"assets/witchinggadgets/blockstates/magic_tile_lock.json",map("variants",map("",map("model","witchinggadgets:block/magic_tile_lock")))));
  variants=map();for(String face:List.of("north","south","west","east"))for(int part=0;part<3;part++)for(boolean open:List.of(false,true)){var boxes=new ArrayList<>();boolean x=face.equals("north")||face.equals("south");int lo=part==0?1:0,hi=part==2?15:16;if(x){boxes.add(box(lo,0,1,hi,2,15));if(part==0)boxes.add(box(0,0,1,1,12,15));if(part==2)boxes.add(box(15,0,1,16,12,15));boxes.add(box(0,0,0,16,12,1));boxes.add(box(0,0,15,16,12,16));boxes.add(!open?box(lo,12,1,hi,16,15):face.equals("north")?box(lo,0,16,hi,14,20):box(lo,0,-4,hi,14,0));}else{boxes.add(box(1,0,lo,15,2,hi));if(part==0)boxes.add(box(1,0,0,15,12,1));if(part==2)boxes.add(box(1,0,15,15,12,16));boxes.add(box(0,0,0,1,12,16));boxes.add(box(15,0,0,16,12,16));boxes.add(!open?box(1,12,lo,15,16,hi):face.equals("west")?box(16,0,lo,20,14,hi):box(-4,0,lo,0,14,hi));}String id="sarcophagus_"+face+"_"+part+"_"+open;jobs.add(d.save(c,"assets/witchinggadgets/models/block/"+id+".json",map("parent","minecraft:block/block","textures",map("side","witchinggadgets:blocks/sarcophagus","top","witchinggadgets:blocks/obsidianplate","particle","witchinggadgets:blocks/sarcophagus"),"elements",boxes)));variants.put("facing="+face+",part="+part+",open="+open,map("model","witchinggadgets:block/"+id));}jobs.add(d.save(c,"assets/witchinggadgets/blockstates/sarcophagus.json",map("variants",variants)));jobs.add(d.save(c,"assets/witchinggadgets/models/item/sarcophagus.json",map("parent","minecraft:block/cube_bottom_top","textures",map("side","witchinggadgets:blocks/sarcophagus","top","witchinggadgets:blocks/obsidianplate","bottom","witchinggadgets:blocks/obsidianplate"))));
 }
}
